    values.iter().sum()
}

fn main() {
    let a = [1, 2, 3];
    let b = [1, 2, 3, 4];
    println!("{}", sum(a)); // N 由实参推断为 3
    println!("{}", sum(b)); // N = 4：另一次单态化
    println!("{}", sum::<2>([9, 9])); // turbofish 显式指定
}
```

