**GitHub Actions完整配置**:
```yaml
# .github/workflows/performance.yml
name: Performance Tests

on:
  push:
    branches: [main, develop]
  pull_request:
    branches: [main]
  schedule:
    # 每天凌晨2点运行性能测试
    - cron: '0 2 * * *'

jobs:
  performance-tests:
    runs-on: ubuntu-latest

    strategy:
      matrix:
        node-version: [20.x, 22.x]

    steps:
      - name: Checkout code
        uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: ${{ matrix.node-version }}
          cache: 'npm'

      - name: Install dependencies
        run: npm ci

      - name: Build application
        run: npm run build

      - name: Start application
        run: |
          npm start &
          sleep 10

      - name: Run Lighthouse CI
        run: |
          npm install -g @lhci/cli@0.12.x
          lhci autorun
        env:
          LHCI_GITHUB_APP_TOKEN: ${{ secrets.LHCI_GITHUB_APP_TOKEN }}

      - name: Run Core Web Vitals tests
        run: npm run test:vitals

      - name: Run bundle analysis
        run: |
          ANALYZE=true npm run build
          node scripts/analyze-bundle.js

      - name: Run load tests
        run: |
          npm install -g k6
          k6 run tests/load/k6-test.js

      - name: Upload performance reports
        uses: actions/upload-artifact@v4
        with:
          name: performance-reports
          path: |
            lighthouse-results/
            bundle-analysis.json
            load-test-summary.json

      - name: Comment PR with performance results
        if: github.event_name == 'pull_request'
        uses: actions/github-script@v6
        with:
          script: |
            const fs = require('fs')

            // 读取Lighthouse结果
            const lighthouseResults = JSON.parse(
              fs.readFileSync('./lighthouse-results/manifest.json', 'utf8')
            )

            // 生成性能报告
            const report = generatePerformanceReport(lighthouseResults)

            // 添加PR评论
            github.rest.issues.createComment({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body: report
            })

  performance-regression:
    runs-on: ubuntu-latest
    needs: performance-tests

    steps:
      - name: Checkout code
        uses: actions/checkout@v4

      - name: Download performance reports
        uses: actions/download-artifact@v4
        with:
          name: performance-reports

      - name: Check for performance regression
        run: node scripts/check-regression.js

      - name: Notify team of regression
        if: failure()
        uses: 8398a7/action-slack@v3
        with:
          status: failure
          text: 'Performance regression detected! Please check the test results.'
        env:
          SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK_URL }}
