```typescript
// app/api/revalidate/route.ts
import { revalidateTag, revalidatePath } from 'next/cache';
import { NextRequest, NextResponse } from 'next/server';

export async function POST(request: NextRequest) {
  const body = await request.json();
  const { tag, path } = body;

  try {
    if (tag) {
      revalidateTag(tag, 'max');  // Next 16：revalidateTag 必须带 profile 第二参数
      return NextResponse.json({ revalidated: true, tag });
    }

    if (path) {
      revalidatePath(path);
      return NextResponse.json({ revalidated: true, path });
    }

    return NextResponse.json(
      { error: 'Invalid request' },
      { status: 400 }
    );
  } catch (error) {
    return NextResponse.json(
      { error: 'Revalidation failed' },
      { status: 500 }
    );
  }
}

// 数据获取 with caching
// lib/api/data-cache.ts
interface CacheOptions {
  revalidate?: number;
  tags?: string[];
}

export async function fetchDataWithCache<T>(
  key: string,
  fetcher: () => Promise<T>,
  options: CacheOptions = {}
): Promise<T> {
  const cacheKey = JSON.stringify({ key, options });

  return fetchWithCache(cacheKey, fetcher, options);
}

async function fetchWithCache<T>(
  cacheKey: string,
  fetcher: () => Promise<T>,
  options: CacheOptions
): Promise<T> {
  // 这里可以实现 Redis 缓存或内存缓存
  const cached = await getFromCache(cacheKey);
  if (cached) {
    return cached;
  }

  const data = await fetcher();
  await setCache(cacheKey, data, options);

  return data;
}
