```typescript
// hooks/useOptimizedData.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useCallback } from 'react';

interface UseOptimizedDataOptions<T> {
  queryKey: string[];
  queryFn: () => Promise<T>;
  staleTime?: number;
  gcTime?: number;
  refetchOnWindowFocus?: boolean;
  refetchOnReconnect?: boolean;
}

export function useOptimizedData<T>({
  queryKey,
  queryFn,
  staleTime = 5 * 60 * 1000, // 5分钟
  gcTime = 10 * 60 * 1000, // 10分钟
  refetchOnWindowFocus = false,
  refetchOnReconnect = true,
}: UseOptimizedDataOptions<T>) {
  return useQuery({
    queryKey,
    queryFn,
    staleTime,
    gcTime,
    refetchOnWindowFocus,
    refetchOnReconnect,
  });
}

// 带乐观更新的数据 Hook
export function useOptimisticData<T>(
  queryKey: string[],
  queryFn: () => Promise<T>,
  updateFn: (oldData: T, newData: Partial<T>) => T
) {
  const queryClient = useQueryClient();

  const { data } = useOptimizedData({
    queryKey,
    queryFn,
  });

  const mutation = useMutation({
    mutationFn: async (newData: Partial<T>) => {
      // 先更新本地状态
      queryClient.setQueryData<T>(queryKey, (oldData) => {
        if (!oldData) return newData as T;
        return updateFn(oldData, newData);
      });

      // 然后发送到服务器
      const response = await fetch('/api/update', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newData),
      });

      if (!response.ok) {
        // 回滚乐观更新
        queryClient.invalidateQueries({ queryKey });
        throw new Error('Update failed');
      }

      return response.json();
    },
    });

  return {
    data,
    mutation,
  };
}
